package dev.hoonex.adofai.loaderinstaller;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import android.view.*;import java.io.*;
public class MainActivity extends Activity{
 LinearLayout col;TextView status,version;boolean busy;File selected;int exportType;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView label(String text,int size,int color){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));col.addView(t);return t;}
 void button(String title,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(title);b.setMinHeight(dp(52));b.setOnClickListener(v->{if(!busy)r.run();});col.addView(b);}
 void task(String name,Work w){if(busy)return;busy=true;status.setText(name+"…");new Thread(()->{String msg;try{msg=w.run();}catch(Throwable e){msg="실패: "+e.getMessage();}String m=msg;runOnUiThread(()->{busy=false;status.setText(m);refresh();});}).start();}
 interface Work{String run()throws Exception;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff171923);getWindow().setNavigationBarColor(0xff171923);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);col=new LinearLayout(this);col.setOrientation(1);col.setPadding(dp(22),dp(24),dp(22),dp(24));col.setBackgroundColor(0xfff5f6fa);scroll.addView(col);setContentView(scroll);
 label("ADOFAI / LOADER",13,0xff5654b9);label("얼불춤 커스텀 맵 설치",27,0xff171923);label("정품 3.3.1 · ARM64 전용 · 개인 기기에서 처리",14,0xff555565);version=label("",16,0xff171923);status=label("준비됨",15,0xff454477);
 button("최신 로더 확인 및 다운로드",()->task("GitHub 확인",()->{Release r=Release.latest();selected=Release.fetch(this,r);getSharedPreferences("state",0).edit().putString("available",r.tag).apply();return "다운로드 및 SHA-256 확인 완료: "+r.tag;}));
 button("원본 백업 + 로더 자동 적용",()->new AlertDialog.Builder(this).setTitle("정품 APK 복사 및 패치").setMessage("정품 설치 파일을 이 앱에 백업한 뒤 최신 로더를 적용하고 개인 키로 서명합니다. 원본 게임, 세이브, 구매 검증은 건드리지 않습니다. 네이티브 업데이트의 실제 호환성은 보장되지 않습니다.").setNegativeButton("취소",null).setPositiveButton("패치", (d,w)->task("APK 패치 중",()->{Release r=Release.latest();selected=Release.fetch(this,r);Patcher.patch(this,selected);getSharedPreferences("state",0).edit().putString("built",r.tag).putString("available",r.tag).apply();return "패치 및 서명 검증 완료. 아직 설치하지 않았습니다.";})).show());
 button("패치된 게임 설치",()->new AlertDialog.Builder(this).setTitle("설치 확인").setMessage("기존 정품과 서명이 달라 처음에는 설치가 거부될 수 있습니다. 정품 삭제는 자동으로 하지 않습니다. 삭제 전 세이브를 별도로 백업하세요. 구매 검증으로 실행이 거부될 수도 있습니다.").setNegativeButton("취소",null).setPositiveButton("Android 설치", (d,w)->{if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));status.setText("설치 허용 후 다시 설치 버튼을 누르세요.");return;}task("설치 요청",()->{Patcher.install(this);return "Android 설치 승인 화면을 확인하세요.";} );}).show());
 button("정품 APK 백업 내보내기",()->{exportType=1;save("ADOFAI-original.apks");});button("패치 APK 세트 내보내기",()->{exportType=2;save("ADOFAI-loader.apks");});
 button("설치 앱 업데이트 확인",()->task("설치 앱 업데이트 확인",()->SelfUpdate.check(this,true)));
 button("설치 앱 업데이트 설치",()->{if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));status.setText("설치 허용 후 다시 누르세요.");return;}task("설치 앱 업데이트 준비",()->{SelfUpdate u=SelfUpdate.latest();if(u.code<=SelfUpdate.installed(this))return "이미 최신 버전입니다.";File f=SelfUpdate.fetch(this,u);SelfUpdate.install(this,u,f);return "Android 설치 승인 화면을 확인하세요.";});});
 button("설치 앱 GitHub",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(SelfUpdate.PAGE))));
 button("GitHub 변경사항 보기",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/Harrot114514/ADOFAI-MobileLevelLoder/releases/latest"))));
 label("업데이트: 약 1시간마다 설치 앱과 로더를 확인하고 자동 다운로드 · 설치는 직접 승인",14,0xff555565);
 label("주의: 원본 게임 파일은 외부 서버에 올라가지 않습니다. 이 앱은 Google Play 인증 우회 기능을 포함하지 않습니다. 원본 APK 백업은 게임 세이브 백업이 아닙니다.",13,0xff555565);
 refresh(); try{Updater.channel(this);if(!Updater.schedule(this))status.setText("자동 업데이트 예약 실패. 수동 확인은 가능합니다.");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},20);}catch(RuntimeException e){status.setText("자동 업데이트 설정 오류: "+e.getMessage());android.util.Log.w("LoaderInstaller","startup",e);}}
 void refresh(){String game="미설치";try{PackageInfo p=getPackageManager().getPackageInfo(Patcher.PKG,0);game=p.versionName+" ("+p.getLongVersionCode()+")";}catch(Exception e){}android.content.SharedPreferences s=getSharedPreferences("state",0);version.setText("설치 앱  1.0.1"+(s.getString("appAvailable","").isEmpty()?"":" → "+s.getString("appAvailable",""))+"\\n게임  "+game+"\n새 로더  "+s.getString("available","확인 전")+"\n패치 결과  "+s.getString("built","없음")+"\n원본 백업  "+(new File(Patcher.original(this),"complete").isFile()?"있음":"없음"));}
 @Override protected void onResume(){super.onResume();if(version!=null){refresh();String m=getSharedPreferences("state",0).getString("install","");if(!m.isEmpty()&&!busy){status.setText(m);getSharedPreferences("state",0).edit().remove("install").apply();}}}
 void save(String name){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,4);}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==4&&res==RESULT_OK&&data!=null){Uri uri=data.getData();int kind=exportType;task("파일 내보내기",()->{File dir=kind==1?Patcher.original(this):Patcher.output(this);if(kind==1)Patcher.backup(this);try(OutputStream o=getContentResolver().openOutputStream(uri)){if(o==null)throw new IOException("저장 파일 열기 실패");Patcher.export(dir,o);}return "내보내기 완료";});}}
}